const growthTeacher=document.createElement('section');growthTeacher.className='teacher-card';growthTeacher.innerHTML='<h2>성장 여권 · 교사 도장</h2><p>하루 10분 이상 공부하고 마무리한 날을 셉니다. 수업일 기준은 아래 버튼으로 기록한 날짜만 세며, 과거 도장은 유지됩니다.</p><label>연속 출석 기준<select id="growthMode"><option value="calendar">매일 · 주말 포함</option><option value="school">교사가 지정한 수업일만</option></select></label><button id="saveGrowthMode">기준 저장</button><button id="markSchoolday">오늘을 수업일로 기록</button><p id="growthSchedule"></p><h3>공동 도시락 시즌</h3><p id="gardenSeasonStatus"></p><label><input type="checkbox" id="gardenAutomatic"> 완성하면 다음 시즌 자동 시작</label><button id="saveGardenAutomatic">자동 시작 설정 저장</button><button id="nextGardenSeason">완료한 시즌을 보관하고 다음 시즌 시작</button><p>학생 재고·도장은 유지되고 초과 기부 재료는 이월됩니다.</p><form id="awardNeighbor"><h3>고마운 이웃 도장 · 학생당 1회</h3><label>학생<select id="awardStudent"></select></label><label>관찰한 도움과 협력<input id="awardReason" minlength="2" maxlength="120" required placeholder="예: 친구의 작물 포장을 도와주었어요"></label><button type="submit">도장 찍어 주기</button></form><p id="growthTeacherStatus" role="status"></p>';document.querySelector('#teacherDashboard').append(growthTeacher);
let growthTeacherRoom='',teacherGardenSeason=1,growthTeacherLoading=false,growthModeDirty=false,gardenAutomaticDirty=false;const beforeGrowthTeacher=show;show=function(d,force=false){beforeGrowthTeacher(d,force);const awardSelect=document.querySelector('#awardStudent'),previousAward=growthTeacherRoom===d.room.id?awardSelect.value:'';awardSelect.innerHTML=d.players.map(p=>`<option value="${p.id}">${esc(p.name)} · ${esc(p.accountName)}</option>`).join('');if(previousAward&&d.players.some(p=>p.id===previousAward))awardSelect.value=previousAward;if(growthTeacherRoom!==d.room.id){growthTeacherRoom=d.room.id;growthModeDirty=false;gardenAutomaticDirty=false}readGrowthTeacher()};
async function readGrowthTeacher(){if(growthTeacherLoading)return;growthTeacherLoading=true;try{const d=await request('/api/growth');if(d.home!==growthTeacherRoom)return;teacherGardenSeason=d.project.season;if(!gardenAutomaticDirty)document.querySelector('#gardenAutomatic').checked=d.project.automatic;document.querySelector('#gardenSeasonStatus').textContent='시즌 '+d.project.season+' · '+(d.project.roles.length===3?'완료':'진행 중')+' · 보관된 최근 시즌 '+d.project.history.length+'개';document.querySelector('#nextGardenSeason').disabled=d.project.roles.length!==3;if(!growthModeDirty)document.querySelector('#growthMode').value=d.mode;document.querySelector('#growthSchedule').textContent='지정한 수업일: '+(d.schooldays.join(', ')||'없음')}catch(e){document.querySelector('#growthTeacherStatus').textContent=e.message}finally{growthTeacherLoading=false}}
async function writeGrowthTeacher(path,body){try{await request(path,body);if(path.endsWith('/policy'))growthModeDirty=false;if(path.endsWith('/season-settings'))gardenAutomaticDirty=false;document.querySelector('#growthTeacherStatus').textContent='선택한 학급에 저장했어요.';await readGrowthTeacher()}catch(e){document.querySelector('#growthTeacherStatus').textContent=e.message}}
document.querySelector('#saveGrowthMode').onclick=()=>writeGrowthTeacher('/api/growth/policy',{mode:document.querySelector('#growthMode').value});document.querySelector('#markSchoolday').onclick=()=>writeGrowthTeacher('/api/growth/schoolday',{});document.querySelector('#awardNeighbor').onsubmit=e=>{e.preventDefault();writeGrowthTeacher('/api/growth/award',{actor:document.querySelector('#awardStudent').value,reason:document.querySelector('#awardReason').value})};

document.querySelector('#saveGardenAutomatic').onclick=()=>writeGrowthTeacher('/api/growth/season-settings',{automatic:document.querySelector('#gardenAutomatic').checked});document.querySelector('#nextGardenSeason').onclick=()=>writeGrowthTeacher('/api/growth/next-season',{season:teacherGardenSeason});

document.querySelector('#growthMode').onchange=()=>growthModeDirty=true;document.querySelector('#gardenAutomatic').onchange=()=>gardenAutomaticDirty=true;
